<dialog class="portal-dialog" id="attendance-editor" aria-labelledby="attendance-editor-title"><button type="button" data-dialog-close aria-label="Tutup"><?= uiIcon('close') ?></button><h2 id="attendance-editor-title">Detail Presensi</h2><form class="ui-form" id="attendance-edit-form"><label>Jam kedatangan<input type="time" id="attendance-edit-arrival"></label><label>Keterangan / Catatan<textarea id="attendance-edit-note" maxlength="2000"></textarea></label><button class="ui-button primary">Terapkan Perubahan</button><p>Tekan Simpan Presensi untuk menyimpan perubahan kelas.</p></form></dialog>
<script>
document.addEventListener('DOMContentLoaded',()=>{
 const rows=[...document.querySelectorAll('[data-attendance-row]')],search=document.querySelector('#attendance-search');let page=1,filter='all',editing=null;const size=6;
 function render(){const query=search?.value.toLocaleLowerCase()||'';const matched=rows.filter(row=>row.dataset.search.includes(query)&&(filter==='all'||row.querySelector('input[type=radio]:checked')?.value===filter));const pages=Math.max(1,Math.ceil(matched.length/size));page=Math.min(page,pages);rows.forEach(row=>row.hidden=true);matched.slice((page-1)*size,page*size).forEach(row=>row.hidden=false);document.querySelector('#attendance-count').replaceChildren(document.createTextNode(`Menampilkan ${Math.min(size,Math.max(0,matched.length-(page-1)*size))} dari ${matched.length} siswa `));const indicator=document.createElement('span');indicator.className='attendance-page-label';indicator.textContent=`Halaman ${page} dari ${pages}`;document.querySelector('#attendance-count').append(indicator);document.querySelector('#attendance-prev').disabled=page===1;document.querySelector('#attendance-next').disabled=page===pages;const nav=document.querySelector('#attendance-pages');nav.replaceChildren();for(let p=1;p<=pages;p++){const b=document.createElement('button');b.type='button';b.textContent=p;b.classList.toggle('active',p===page);if(p===page)b.setAttribute('aria-current','page');b.onclick=()=>{page=p;render();};nav.append(b);}}
 function updateRow(row){const status=row.querySelector('input[type=radio]:checked')?.value;const arrival=row.querySelector('[name^=arrival]').value;const badge=row.querySelector('[data-arrival-display]');badge.hidden=status!=='hadir'||!arrival;badge.querySelector('span').textContent=arrival+' WIB';row.querySelector('[data-arrival-empty]').hidden=!badge.hidden;}
 if(!search)return;search.addEventListener('input',()=>{page=1;render();});document.querySelectorAll('[data-attendance-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.attendanceFilter;page=1;document.querySelectorAll('[data-attendance-filter]').forEach(x=>x.classList.toggle('active',x===b));render();});document.querySelector('#attendance-prev').onclick=()=>{page--;render();};document.querySelector('#attendance-next').onclick=()=>{page++;render();};document.querySelector('#mark-all-present').onclick=()=>{rows.forEach(r=>{r.querySelector('input[value=hadir]').checked=true;updateRow(r);});render();};
 rows.forEach(row=>{row.querySelector('.attendance-edit').onclick=()=>{editing=row;document.querySelector('#attendance-editor-title').textContent=row.querySelector('.attendance-student strong').textContent;document.querySelector('#attendance-edit-arrival').value=row.querySelector('[name^=arrival]').value;document.querySelector('#attendance-edit-note').value=row.querySelector('[name^=notes]').value;document.querySelector('#attendance-editor').showModal();};row.querySelectorAll('input[type=radio]').forEach(input=>input.addEventListener('change',()=>{updateRow(row);render();}));});
 document.querySelector('#attendance-edit-form').addEventListener('submit',event=>{event.preventDefault();if(!editing)return;editing.querySelector('[name^=arrival]').value=document.querySelector('#attendance-edit-arrival').value;const note=document.querySelector('#attendance-edit-note').value;editing.querySelector('[name^=notes]').value=note;editing.querySelector('[data-note-display]').textContent=note||'\u2013';updateRow(editing);document.querySelector('#attendance-editor').close();});render();
});
</script>
<?php require __DIR__.'/../ui_end.php'; ?>
